package com.auth0.jwt.interfaces;

import java.time.Instant;

/**
 * Class that represents a Json Web Token that was decoded from it's string representation.
 */
public interface DecodedJWT extends Payload, Header {
    /**
     * Getter for the String Token used to create this JWT instance.
     *
     * @return the String Token.
     */
    String getToken();

    /**
     * Getter for the Header contained in the JWT as a Base64 encoded String.
     * This represents the first part of the token.
     *
     * @return the Header of the JWT.
     */
    String getHeader();

    /**
     * Getter for the Payload contained in the JWT as a Base64 encoded String.
     * This represents the second part of the token.
     *
     * @return the Payload of the JWT.
     */
    String getPayload();

    /**
     * Getter for the Signature contained in the JWT as a Base64 encoded String.
     * This represents the third part of the token.
     *
     * @return the Signature of the JWT.
     */
    String getSignature();

    /**
     * Checks if the token is expired at the current time.
     * This checks the "exp" (expiration time) claim.
     * If the "exp" claim is not present, the token is considered not expired.
     *
     * @return true if the token is expired, false otherwise.
     */
    default boolean isExpired() {
        return isExpired(Instant.now());
    }

    /**
     * Checks if the token is expired at the given time.
     * This checks the "exp" (expiration time) claim.
     * If the "exp" claim is not present, the token is considered not expired.
     *
     * @param at the time to check expiration against.
     * @return true if the token is expired at the given time, false otherwise.
     * @throws IllegalArgumentException if the provided time is null.
     */
    default boolean isExpired(Instant at) {
        if (at == null) {
            throw new IllegalArgumentException("The time to check expiration against cannot be null.");
        }
        Instant exp = getExpiresAtAsInstant();
        return exp != null && at.isAfter(exp);
    }

    /**
     * Checks if the token is not yet valid (before "nbf" claim) at the current time.
     * This checks the "nbf" (not before) claim.
     * If the "nbf" claim is not present, the token is considered valid (not before now).
     *
     * @return true if the token is not yet valid, false otherwise.
     */
    default boolean isNotBefore() {
        return isNotBefore(Instant.now());
    }

    /**
     * Checks if the token is not yet valid (before "nbf" claim) at the given time.
     * This checks the "nbf" (not before) claim.
     * If the "nbf" claim is not present, the token is considered valid (not before the given time).
     *
     * @param at the time to check the "nbf" claim against.
     * @return true if the token is not yet valid at the given time, false otherwise.
     * @throws IllegalArgumentException if the provided time is null.
     */
    default boolean isNotBefore(Instant at) {
        if (at == null) {
            throw new IllegalArgumentException("The time to check the 'nbf' claim against cannot be null.");
        }
        Instant nbf = getNotBeforeAsInstant();
        return nbf != null && at.isBefore(nbf);
    }

    /**
     * Checks if the token is currently valid (not expired and not before "nbf" claim).
     * This checks both the "exp" (expiration time) and "nbf" (not before) claims.
     * If either claim is not present, it is not considered for validity.
     *
     * @return true if the token is valid, false otherwise.
     */
    default boolean isValid() {
        return isValid(Instant.now());
    }

    /**
     * Checks if the token is valid at the given time (not expired and not before "nbf" claim).
     * This checks both the "exp" (expiration time) and "nbf" (not before) claims.
     * If either claim is not present, it is not considered for validity.
     *
     * @param at the time to check validity against.
     * @return true if the token is valid at the given time, false otherwise.
     * @throws IllegalArgumentException if the provided time is null.
     */
    default boolean isValid(Instant at) {
        if (at == null) {
            throw new IllegalArgumentException("The time to check validity against cannot be null.");
        }
        return !isExpired(at) && !isNotBefore(at);
    }
}
